'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useId, useRef } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon, BellIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { APP, NOTES } from './data';
import { NewsRow } from './news-row';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  unreadCountOf,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const PANEL_SHOWN = { opacity: 1, scale: 1 };

const PANEL_HIDDEN = { opacity: 0, scale: 0.95 };

const PANEL_FADED = { opacity: 0, scale: 1 };

const PANEL_ARRIVE = { duration: 0.15, ease: [0.23, 1, 0.32, 1] as const };

const PANEL_LEAVE = { duration: 0.1, ease: [0.23, 1, 0.32, 1] as const };

function panelStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return PANEL_FADED;
  }
  return PANEL_HIDDEN;
}

const PILL_SHOWN = { opacity: 1, scale: 1 };

const PILL_HIDDEN = { opacity: 0, scale: 0.6 };

const PILL_TRANSITION = { duration: 0.15, ease: [0.2, 0, 0, 1] as const };

function pillStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return PANEL_FADED;
  }
  return PILL_HIDDEN;
}

function spokenLineOf(unread: number) {
  if (unread === 0) {
    return 'You are up to date';
  }
  if (unread === 1) {
    return '1 note unread';
  }
  return `${unread} notes unread`;
}

export default function Changelog03() {
  const { ref, isAutoplaying, state, act, pressed, isFinished, restart } =
    useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const panelId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const { isOpen, readIds } = state;
  const unread = unreadCountOf(readIds);
  const hasUnread = unread > 0;
  const message = spokenUnless(isAutoplaying, spokenLineOf(unread));
  const canReplay = isFinished && !isAutoplaying;
  const listensOutside = isOpen && !isAutoplaying;

  useEffect(() => {
    if (!listensOutside) {
      return;
    }
    function closeFromOutside(event: PointerEvent) {
      const wrapper = wrapperRef.current;
      const target = event.target;
      const isInside = target instanceof Node && wrapper?.contains(target);
      if (!isInside) {
        act({ type: 'closed' });
      }
    }
    document.addEventListener('pointerdown', closeFromOutside);
    return () => document.removeEventListener('pointerdown', closeFromOutside);
  }, [listensOutside, act]);

  function toggle() {
    if (isOpen) {
      act({ type: 'closed' });
      return;
    }
    act({ type: 'opened' });
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape' && isOpen) {
      event.preventDefault();
      act({ type: 'closed' });
      triggerRef.current?.focus();
    }
  }

  return (
    <div ref={ref} className='@container px-4 py-10 @2xl:px-6 @2xl:py-16'>
      <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] relative mx-auto min-h-[30rem] max-w-3xl rounded-2xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <header className='flex h-14 items-center gap-2 px-4'>
          <CompanyMark seed={APP.name} size='lg' />
          <span className='text-sm font-semibold'>{APP.name}</span>
          <div className='ms-auto flex items-center gap-2'>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
            <div
              ref={wrapperRef}
              onKeyDown={closeOnEscape}
              className='relative'
            >
              <Button
                ref={triggerRef}
                type='button'
                variant='outline'
                aria-expanded={isOpen}
                aria-haspopup='dialog'
                aria-controls={panelId}
                onClick={toggle}
                className={cn(pressedQuietOf(pressed === 'trigger'))}
              >
                <BellIcon />
                What’s new
                <AnimatePresence initial={false}>
                  {hasUnread && (
                    <motion.span
                      key='unread'
                      initial={pillStartOf(shouldReduceMotion)}
                      animate={PILL_SHOWN}
                      exit={pillStartOf(shouldReduceMotion)}
                      transition={PILL_TRANSITION}
                      className='bg-primary text-primary-foreground flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[11px] font-medium'
                    >
                      <MotionNumber value={unread} />
                      <span className='sr-only'> unread</span>
                    </motion.span>
                  )}
                </AnimatePresence>
              </Button>
              <AnimatePresence initial={false}>
                {isOpen && (
                  <motion.div
                    key='panel'
                    id={panelId}
                    role='dialog'
                    aria-label='What’s new'
                    initial={panelStartOf(shouldReduceMotion)}
                    animate={PANEL_SHOWN}
                    exit={{
                      ...panelStartOf(shouldReduceMotion),
                      transition: PANEL_LEAVE,
                    }}
                    transition={PANEL_ARRIVE}
                    className='surface-raised absolute end-0 top-full z-10 mt-2 w-[min(22rem,calc(100cqw_-_2rem))] origin-top-right rounded-xl'
                  >
                    <div className='flex items-center justify-between gap-2 px-3.5 pt-3 pb-1'>
                      <h3 className='text-sm font-medium'>What’s new</h3>
                      <Button
                        type='button'
                        variant='ghost'
                        size='sm'
                        disabled={!hasUnread}
                        onClick={() => act({ type: 'allRead' })}
                        className={cn(
                          'text-primary-ink',
                          pressedQuietOf(pressed === 'mark-all')
                        )}
                      >
                        Mark all read
                      </Button>
                    </div>
                    <ul className='flex flex-col p-1.5'>
                      {NOTES.map((note) => (
                        <NewsRow
                          key={note.id}
                          note={note}
                          isUnread={!readIds.includes(note.id)}
                          isPressed={pressed === `note-${note.id}`}
                          onRead={(id) => act({ type: 'read', id })}
                        />
                      ))}
                    </ul>
                    <div className='flex min-h-11 items-center justify-between gap-3 px-3.5 pb-3'>
                      <p className='text-muted-foreground flex items-center gap-1.5 text-xs'>
                        {!hasUnread && (
                          <>
                            <DrawnCheck tone='success' entrance='draw' />
                            You are up to date
                          </>
                        )}
                      </p>
                      <Button
                        variant='ghost'
                        size='sm'
                        nativeButton={false}
                        render={<a href={APP.allNotesHref} />}
                      >
                        All release notes
                        <ArrowRightIcon />
                      </Button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </header>
        <div className='px-4 pt-2'>
          <Badge variant='secondary'>{APP.badge}</Badge>
        </div>
      </div>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';

import { KIND_STYLES, type Note } from './data';

function dotOf(isUnread: boolean) {
  if (isUnread) {
    return 'scale-100 opacity-100';
  }
  return 'scale-0 opacity-0';
}

function titleToneOf(isUnread: boolean) {
  if (isUnread) {
    return 'font-medium text-foreground';
  }
  return 'text-muted-foreground';
}

type NewsRowProps = {
  note: Note;
  isUnread: boolean;
  isPressed: boolean;
  onRead: (id: string) => void;
};

export function NewsRow({ note, isUnread, isPressed, onRead }: NewsRowProps) {
  const kind = KIND_STYLES[note.kind];

  return (
    <li>
      <a
        href={note.href}
        onClick={() => onRead(note.id)}
        className={cn(
          'hover:bg-foreground/[0.04] flex items-start gap-3 rounded-md px-2.5 py-2.5 transition-colors duration-100',
          pressedQuietOf(isPressed),
          FOCUS_RING
        )}
      >
        <span
          aria-hidden='true'
          className='mt-[7px] flex size-2 shrink-0 items-center justify-center'
        >
          <span
            className={cn(
              'bg-primary size-2 rounded-full transition-[scale,opacity] duration-200 ease-(--ease-out-strong)',
              dotOf(isUnread)
            )}
          />
        </span>
        <span className='flex min-w-0 flex-1 flex-col gap-0.5'>
          <span className='flex items-baseline gap-2'>
            <span
              className={cn(
                'min-w-0 flex-1 truncate text-[13px] transition-colors duration-200',
                titleToneOf(isUnread)
              )}
            >
              {note.title}
              {isUnread && <span className='sr-only'>, unread</span>}
            </span>
            <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
              {note.date}
            </span>
          </span>
          <span className='text-muted-foreground line-clamp-1 text-xs'>
            {note.summary}
          </span>
        </span>
        <Chip color={kind.color} className='mt-0.5 hidden @sm:inline-flex'>
          {kind.label}
        </Chip>
      </a>
    </li>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import { NOTES, READ_AT_START } from './data';

export type NewsState = {
  isOpen: boolean;
  readIds: string[];
};

export type NewsAction =
  | { type: 'opened' }
  | { type: 'closed' }
  | { type: 'read'; id: string }
  | { type: 'allRead' };

type Step = SessionStep<NewsState, NewsAction>;

export const INITIAL: NewsState = {
  isOpen: false,
  readIds: READ_AT_START,
};

export function unreadCountOf(readIds: string[]) {
  const unread = NOTES.filter((note) => !readIds.includes(note.id));
  return unread.length;
}

function read(state: NewsState, id: string): NewsState {
  if (state.readIds.includes(id)) {
    return state;
  }
  return { ...state, readIds: [...state.readIds, id] };
}

export function reducer(state: NewsState, action: NewsAction): NewsState {
  switch (action.type) {
    case 'opened':
      return { ...state, isOpen: true };
    case 'closed':
      return { ...state, isOpen: false };
    case 'read':
      return read(state, action.id);
    case 'allRead':
      return { ...state, readIds: NOTES.map((note) => note.id) };
  }
}

/**
 * Someone opens the list, reads two notes so the count rolls down, marks the rest as read and
 * closes it: a round ends with nothing left to read, and starts again with three unread.
 */
export const SCRIPT: Step[] = [
  {
    after: 2000,
    by: 'demo',
    press: 'trigger',
    action: { type: 'opened' },
  },
  {
    after: 2200,
    by: 'demo',
    press: 'note-quiet-hours',
    action: { type: 'read', id: 'quiet-hours' },
  },
  {
    after: 1500,
    by: 'demo',
    press: 'note-zone-strip',
    action: { type: 'read', id: 'zone-strip' },
  },
  {
    after: 1800,
    by: 'demo',
    press: 'mark-all',
    action: { type: 'allRead' },
  },
  {
    after: 1900,
    by: 'demo',
    press: 'trigger',
    action: { type: 'closed' },
  },
];

/** Under reduced motion the list is open with three notes still unread. */
export const RESTING: NewsState = {
  isOpen: true,
  readIds: READ_AT_START,
};

export const LOOP_AFTER_MS = 2600;

export type ChangeKind = 'new' | 'improved' | 'fixed';

export type Note = {
  id: string;
  date: string;
  title: string;
  kind: ChangeKind;
  summary: string;
  href: string;
};

export const KIND_STYLES: Record<ChangeKind, { label: string; color: string }> =
  {
    new: { label: 'New', color: 'var(--primary)' },
    improved: { label: 'Improved', color: 'var(--info)' },
    fixed: { label: 'Fixed', color: 'var(--success)' },
  };

export const APP = {
  name: 'Tidepool',
  badge: 'Sample release notes',
  allNotesHref: '#all-release-notes',
};

export const NOTES: Note[] = [
  {
    id: 'quiet-hours',
    date: '27 Oct',
    title: 'Quiet hours for every teammate',
    kind: 'new',
    summary: 'Invites inside your quiet hours suggest other times.',
    href: '#note-quiet-hours',
  },
  {
    id: 'zone-strip',
    date: '14 Oct',
    title: 'A time zone strip on every invite',
    kind: 'improved',
    summary: 'See each guest’s local time, from Kinshasa to Lisbon.',
    href: '#note-zone-strip',
  },
  {
    id: 'recurring-shift',
    date: '6 Oct',
    title: 'Recurring events keep their place',
    kind: 'fixed',
    summary: 'A weekly event no longer moves when clocks change.',
    href: '#note-recurring-shift',
  },
  {
    id: 'room-search',
    date: '23 Sep',
    title: 'Find a room by what it has',
    kind: 'new',
    summary: 'Search free rooms by screen, whiteboard or seats.',
    href: '#note-room-search',
  },
  {
    id: 'agenda-notes',
    date: '9 Sep',
    title: 'Agenda notes follow the event',
    kind: 'improved',
    summary: 'Notes stay with a meeting when it moves to another day.',
    href: '#note-agenda-notes',
  },
];

export const READ_AT_START: string[] = ['room-search', 'agenda-notes'];
